using System.Net.Http;using System.Net.Http.Headers;using System.Net.Http.Json;using Vitakora.Shared;
namespace Vitakora.Client.Services;
public sealed class ApiClient(string baseUrl){private readonly HttpClient _http=new(){BaseAddress=new Uri(baseUrl)};public async Task<List<WorkstationDto>> GetWorkstationsAsync()=>await _http.GetFromJsonAsync<List<WorkstationDto>>("api/workstations")??[];public async Task<LoginResponse?> LoginAsync(LoginRequest r){var res=await _http.PostAsJsonAsync("api/auth/login",r);return res.IsSuccessStatusCode?await res.Content.ReadFromJsonAsync<LoginResponse>():null;}public async Task<List<DirectoryItemDto>> GetDirectoryAsync(string token){_http.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);return await _http.GetFromJsonAsync<List<DirectoryItemDto>>("api/directory")??[];}}
